int _knowledgeCheckEstimateSize(
  KnowledgeCheck object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.explanation.length * 3;
  bytesCount += 3 + object.options.length * 3;
  {
    for (var i = 0; i < object.options.length; i++) {
      final value = object.options[i];
      bytesCount += value.length * 3;
    }
  }
  bytesCount += 3 + object.question.length * 3;
  return bytesCount;
}

void _knowledgeCheckSerialize(
  KnowledgeCheck object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeLong(offsets[0], object.correctOptionIndex);
  writer.writeString(offsets[1], object.explanation);
  writer.writeLong(offsets[2], object.learningUnitId);
  writer.writeStringList(offsets[3], object.options);
  writer.writeString(offsets[4], object.question);
}

KnowledgeCheck _knowledgeCheckDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = KnowledgeCheck();
  object.correctOptionIndex = reader.readLong(offsets[0]);
  object.explanation = reader.readString(offsets[1]);
  object.id = id;
  object.learningUnitId = reader.readLong(offsets[2]);
  object.options = reader.readStringList(offsets[3]) ?? [];
  object.question = reader.readString(offsets[4]);
  return object;
}

P _knowledgeCheckDeserializeProp<P>(
  IsarReader reader,
  int propertyId,
  int offset,
  Map<Type, List<int>> allOffsets,
) {
  switch (propertyId) {
    case 0:
